/* ============================================================
 *  DBG+ #1: DOM 僵死 / 空白 / 点击无反应 探针 (MutationObserver + ClickDeadWatch)
 * ==========================================================*/
try{
  // 观察 4 个主 Tab 根区域：#today-body / #page-cn / #page-wu / #page-tools (如果存在)
  window.__domHeartbeat = {
    lastPaint: Date.now(),
    lastTabChange: Date.now(),
    deadCount: 0,
    lastClicks: []
  };
  var __hosts = [];
  try{
    ['today-body','page-cn','page-wu','page-tools','history-body'].forEach(function(id){
      var el = document.getElementById(id);
      if(el) __hosts.push(el);
    });
  }catch(_){ __hosts = []; }

  // 轮询兜底：DOM ready 后再找 2 次
  function __rebindHosts(){
    try{
      ['today-body','page-cn','page-wu','page-tools','history-body'].forEach(function(id){
        var el = document.getElementById(id);
        if(el && __hosts.indexOf(el)<0) __hosts.push(el);
      });
    }catch(_){}
  }
  setTimeout(__rebindHosts, 800); setTimeout(__rebindHosts, 2500);

  // MutationObserver: 有任何 childList/attribute 变动认为有活动（记 lastPaint）
  try{
    if(typeof MutationObserver !== 'undefined'){
      var mo = new MutationObserver(function(muts){
        try{
          window.__domHeartbeat.lastPaint = Date.now();
          window.__domHeartbeat.deadCount = 0;
        }catch(_){}
      });
      // body 级 + 逐个 host 级观察
      try{ mo.observe(document.documentElement, { childList:true, subtree:true, attributes:true, attributeFilter:['class','style','id'] }); }catch(_){}
      __hosts.forEach(function(el){ try{ mo.observe(el, { childList:true, subtree:true, attributes:true }); }catch(_){} });
    }
  }catch(_){ mo = null; }

  // 全局 click 死状态：点击后 3 秒内既没 MutationObserver 活动（或活动数<1），也没 DOM 容器 innerHTML size 变化 → 给"点了没反应"提示
  try{
    document.addEventListener && document.addEventListener('click', function(e){
      try{
        var t = e.target; if(!t) return;
        var isBtn = (t.tagName==='BUTTON' || t.closest && (t.closest('button') || t.closest('[onclick]')));
        if(!isBtn) return;
        window.__domHeartbeat.lastClicks.push({ts:Date.now(), htmlSize: 0});
        try{ var r = document.getElementById('app') || document.body; window.__domHeartbeat.lastClicks[window.__domHeartbeat.lastClicks.length-1].htmlSize = (r&&r.innerHTML)?r.innerHTML.length:0; }catch(_){}
        if(window.__domHeartbeat.lastClicks.length>8) window.__domHeartbeat.lastClicks.shift();
      }catch(_){}
    }, true);
  }catch(_){}

  // 每 3 秒做一次健康扫描
  setInterval(function(){
    try{
      var now = Date.now();
      var hb = window.__domHeartbeat;
      // case A: 3s 内宿主区没任何 Mutation + 页面初始化>6s 且 HTML size < 600 → 疑似僵死
      var app = document.getElementById('app') || document.body;
      var curSz = (app && app.innerHTML) ? app.innerHTML.length : 0;
      var idleSec = Math.round((now - hb.lastPaint)/1000);
      var pageAge = Math.round((now - (window._dbgHealth&&window._dbgHealth.startAt||now))/1000);
      if(idleSec >= 9 && pageAge > 8 && curSz < 2000){
        hb.deadCount++;
        if(hb.deadCount === 1){
          window._errLog.push('DOM_IDLE 无变动>'+idleSec+'s, html='+curSz+', pageAge='+pageAge+'s → 疑似僵死/白屏');
          try{
            if(typeof showErrBanner === 'function'){
              showErrBanner('页面 '+idleSec+' 秒没变化了（大小='+curSz+'）可能僵死', {message:'DOM_IDLE freeze htmlsz='+curSz, stack:'idleSec='+idleSec});
            } else if(typeof showToastBottom === 'function'){
              showToastBottom('😶 页面 '+idleSec+' 秒没变化？下拉/刷新重试');
            }
          }catch(_){}
        }
      } else if(idleSec < 3){
        hb.deadCount = 0;
      }
      // case B: ClickDeadWatch — 检查最近 1 次 click (3.5~4s 前) 后 innerHTML size 是否增长 >0.5%
      try{
        var clicks = hb.lastClicks;
        for(var ci=0;ci<clicks.length;ci++){
          var cc = clicks[ci];
          if(!cc || cc.checked) continue;
          if(now - cc.ts < 3500) continue;
          cc.checked = true;
          var sizeBefore = cc.htmlSize;
          if(sizeBefore < 300) continue;
          var sizeNow = curSz;
          if(sizeNow < 300) continue;
          var deltaPct = Math.abs(sizeNow-sizeBefore) / sizeBefore;
          if(deltaPct < 0.005){
            // click 后 DOM 没变化 → 可能按钮点了没反应
            window._errLog.push('CLICK_DEAD 点击后 HTML 变动 '+(deltaPct*100).toFixed(2)+'% <0.5% sz_before='+sizeBefore+' sz_now='+sizeNow);
          }
        }
      }catch(_){}
    }catch(_){}
  }, 3000);
}catch(_){}
