/* ============================================================
 *  DBG+ #3: 标准异常报告 v2 (buildLastErrorReport)
 *    涵盖: 设备指纹 / 健康快照 / 分类建议 / localStorage 摘要 / 草稿 dirty flag / 最近 15 条 log
 * ==========================================================*/
function buildLastErrorReport(info, msg, errOrStack){
  try{
    var now = new Date();
    var lines = [];
    var ua = typeof navigator !== 'undefined' ? (navigator.userAgent||'') : '';
    var ver = typeof ZHIMING_BUILD !== 'undefined' ? ZHIMING_BUILD : '?';
    lines.push('=== 知命V2 异常报告 (v2) ===');
    lines.push('Build : '+ver);
    lines.push('Time  : '+now.toLocaleString());
    lines.push('UA    : '+ua);
    // 分类等级与建议
    info = info || classifyErr(msg, errOrStack && (typeof errOrStack==='string'?errOrStack: (errOrStack.stack||(errOrStack.message||''))));
    lines.push('分类  : ['+info.code+'] '+humanReadableLevel(info.level)+' — '+info.title);
    lines.push('原因  : '+info.why);
    lines.push('建议修复:');
    (info.fix||[]).forEach(function(s,i){ lines.push('  S'+(i+1)+': '+s); });
    lines.push('');
    // 设备 & 环境指纹
    lines.push('--- 设备 / 环境 ---');
    var sc = (typeof screen !== 'undefined') ? (screen.width+'x'+screen.height) : '?';
    var vp = (typeof window !== 'undefined' && window.innerWidth) ? (window.innerWidth+'x'+window.innerHeight) : '?';
    var dpr = (typeof window !== 'undefined' && window.devicePixelRatio) || 1;
    var lang = (typeof navigator !== 'undefined' && navigator.language) || '?';
    var plat = (typeof navigator !== 'undefined' && (navigator.platform||navigator.userAgentData && navigator.userAgentData.platform)) || '?';
    var onLine = (typeof navigator !== 'undefined' && typeof navigator.onLine === 'boolean') ? (navigator.onLine ? 'online' : 'offline') : '?';
    var touch = (typeof navigator !== 'undefined' && navigator.maxTouchPoints ? navigator.maxTouchPoints : (('ontouchstart' in (typeof window!=='undefined'?window:{})) ? 1 : 0));
    lines.push('屏幕 : '+sc+'  视口 : '+vp+'  dpr : '+dpr);
    lines.push('系统 : '+plat+'  语言 : '+lang+'  网络 : '+onLine+'  触控点 : '+touch);
    try{ if(typeof performance !== 'undefined' && performance.memory){ var pm = performance.memory; lines.push('JS 堆: '+Math.round(pm.usedJSHeapSize/1048576)+'MB / '+Math.round(pm.jsHeapSizeLimit/1048576)+'MB (used/limit)'); } }catch(_){}
    lines.push('');
    // 健康面板快照
    lines.push('--- 健康面板快照 ---');
    try{
      var h = window._dbgHealth || {};
      var avgF=0; if(h.fpsSamples && h.fpsSamples.length){var t=0;for(var i=0;i<h.fpsSamples.length;i++)t+=h.fpsSamples[i]; avgF=Math.round(t/h.fpsSamples.length);}
      lines.push('运行时长(min): ' + Math.round((Date.now()-(h.startAt||now.getTime()))/60000));
      lines.push('即时FPS: ' + (h.fps||0) + '  平均FPS: ' + avgF + '  FPS<20次数: ' + (h.frameMiss||0));
      lines.push('LS使用 (KB): ' + Math.round((h.lsUsage||0)/1024));
      lines.push('JS堆 (MB)  : ' + (h.memUsedMB||'?'));
      if(window.__domHeartbeat){ var hd=window.__domHeartbeat; lines.push('DOM最后变动 (s前): '+Math.max(0, Math.round((now.getTime()-hd.lastPaint)/1000)) + '  僵死告警次数: '+(hd.deadCount||0)); }
    }catch(e){ lines.push('health err: '+e.message); }
    lines.push('');
    // 当前 Tabs + 聚焦元素
    lines.push('--- 应用上下文 ---');
    try{ if(typeof _getActiveTabs === 'function'){ lines.push('当前 Tabs: '+_getActiveTabs()); } }catch(_){}
    try{ var ae = document && document.activeElement; var aeId = ae && (ae.id || (ae.tagName && ae.tagName)); if(aeId) lines.push('当前焦点元素: id/type='+aeId + (ae&&ae['value']&&typeof ae['value']==='string' ? ' valueLen='+ae['value'].length : '')); }catch(_){}
    try{ if(typeof scrollY !== 'undefined') lines.push('滚动 Y: ' + (window.scrollY||0) + 'px'); }catch(_){}
    lines.push('');
    // localStorage 摘要 (10类草稿 flag + history 条目)
    lines.push('--- localStorage 摘要 ---');
    try{
      var histKey = HIST_KEY || 'zhiming_v2_history';
      var histCount = 0;
      try{ var histArr = JSON.parse(localStorage.getItem(histKey)||'[]'); if(Array.isArray(histArr)) histCount = histArr.length; }catch(_){ histCount = 0; }
      lines.push('历史条目: '+histCount);
      if(typeof DRAFT_TYPES !== 'undefined'){
        for(var di=0;di<DRAFT_TYPES.length;di++){
          var dt = DRAFT_TYPES[di];
          var pf = (typeof DRAFT_KEY_PREFIX !== 'undefined' ? DRAFT_KEY_PREFIX : 'zhiming_v2_draft_');
          var bytes = (localStorage.getItem(pf+dt)||'').length;
          var dirty = localStorage.getItem(pf+dt+(typeof DRAFT_DIRTY_SUFFIX!=='undefined'?DRAFT_DIRTY_SUFFIX:'_dirty')) === '1';
          if(bytes>0 || dirty) lines.push('草稿['+dt+'] bytes='+bytes+' dirty='+dirty);
        }
      }
      // 其它 key 汇总
      var allLen = 0; var topK = [];
      for(var ki=0;ki<localStorage.length;ki++){
        var kn = localStorage.key(ki); if(!kn) continue;
        var kv = localStorage.getItem(kn)||''; allLen += kn.length + kv.length;
        topK.push({k:kn, l:kv.length});
      }
      topK.sort(function(a,b){return b.l-a.l;});
      topK = topK.slice(0,5);
      lines.push('LS总大小: KB=' + Math.round(allLen/1024) + '  本地总 key 数: ' + localStorage.length);
      lines.push('LS Top5: ' + topK.map(function(x){return x.k+'('+Math.round(x.l/1024)+'KB)';}).join(', '));
    }catch(e){ lines.push('ls err: '+e.message); }
    lines.push('');
    // 最近 15 条 _errLog
    lines.push('--- _errLog 最近 15 条 ---');
    (window._errLog||[]).slice(-15).forEach(function(l,i){ lines.push('  ['+((window._errLog||[]).length-15+i)+'] '+l); });
    lines.push('');
    // 异常原始信息
    lines.push('--- 原始错误详情 ---');
    lines.push('显示消息: '+msg);
    if(errOrStack){
      if(typeof errOrStack === 'string') lines.push('stack/msg: '+errOrStack);
      else { lines.push('message: '+(errOrStack.message||'')); lines.push('stack   : '+(errOrStack.stack||'')); }
    }
    lines.push('');
    lines.push('=== 知命V2 异常报告 END ===');
    return lines.join('\n');
  }catch(e){ try{ return '异常报告生成失败: '+String(e&&e.message||e)+'\n原始 msg='+msg; }catch(_){ return String(msg||''); } }
}
try{ window.buildLastErrorReport = buildLastErrorReport; }catch(_){}

